func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/profesionales/solicitudes", wrapper.ListarSolicitudesProfesionales)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/profesionales/listas", wrapper.ListasAsignables)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/profesionales/resumen", wrapper.ResumenProfesionales)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/profesionales/aprobacion", wrapper.AprobarSolicitud)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/profesionales/{id}/enlace", wrapper.EnlaceDeAcceso)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/profesionales/rechazo", wrapper.RechazarSolicitud)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/profesionales/solicitud", wrapper.SolicitarAccesoProfesional)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/profesionales/estado", wrapper.EstadoProfesional)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/eventos", wrapper.ListarEventosAdmin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/eventos", wrapper.CrearEvento)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/admin/eventos/{id}", wrapper.BorrarEvento)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/eventos/{id}/recordatorio", wrapper.RecordarEvento)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/eventos/{id}/asistentes", wrapper.AsistentesDeEvento)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/admin/eventos/estado", wrapper.CambiarEstadoEvento)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/admin/eventos/asistencia", wrapper.MarcarAsistencia)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/eventos/recordatorios", wrapper.MandarRecordatorios)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/eventos/inscripcion", wrapper.AnotarseAEvento)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/eventos/aviso-por-pago", wrapper.AvisarInscripcionPorPago)

	return m
}

